                    Text(initials)
                        .monarchTextStyle(.caption)
                        .fontWeight(.semibold)
                        .foregroundStyle(theme.colors.infoStrong)
                        .frame(width: theme.spacing.space6, height: theme.spacing.space6)
                        .background(Circle().fill(theme.colors.infoSubtle))
                }
                Text(title)
                    .monarchTextStyle(.bodySmall)
                    .foregroundStyle(theme.colors.textDefault)
                Spacer(minLength: 0)
                if isCurrent {
                    Circle()
                        .fill(theme.colors.accentSolid)
                        .frame(width: theme.spacing.space1_5, height: theme.spacing.space1_5)
                }
            }
            .padding(.horizontal, theme.spacing.space3)
            .frame(maxWidth: .infinity, minHeight: 44, alignment: .leading)
            .contentShape(Rectangle())
        }
        .buttonStyle(.plain)
        .accessibilityAddTraits(isCurrent ? .isSelected : [])
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            Button {
                isOpen.toggle()
            } label: {
                MonarchAvatar(image: nil, name: "Sam Rivera", size: .sm, isDecorative: true)
                    .monarchMinimumHitTarget()
            }
            .buttonStyle(.plain)
            .accessibilityLabel("Account menu for " + "Sam Rivera")
            .accessibilityValue(isOpen ? "expanded" : "collapsed")
            if isOpen {
                VStack(alignment: .leading, spacing: 0) {
                    VStack(alignment: .leading, spacing: theme.spacing.space1) {
                        Text("Sam Rivera")
                            .monarchTextStyle(.bodyStrong)
                            .foregroundStyle(theme.colors.textDefault)
                        Text(verbatim: "sam@example.com")
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                    }
                    .padding(.horizontal, theme.spacing.space3)
                    .padding(.vertical, theme.spacing.space3)
                    MonarchDivider()
                    row("Profile", systemImage: "person") {}
                    row("Settings", systemImage: "gearshape") {}
                    MonarchDivider()
