                    row("Harbor Labs", initials: "HL", isCurrent: workspace == "ws-2") { workspace = "ws-2" }
                    MonarchDivider()
                    sectionTitle("Theme")
                    row("Light", isCurrent: scheme == .light) { scheme = .light }
                    row("Dark", isCurrent: scheme == .dark) { scheme = .dark }
                    row("System", isCurrent: scheme == .system) { scheme = .system }
                    MonarchDivider()
                    row("Keyboard shortcuts") {}
