/// create-workspace-dialog: From a workspace switcher
private struct CreateWorkspaceDialogExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isPresented = PreviewMode.presented ? true : false
    @State private var name = "Acme Inc."
    @State private var username = ""
    @State private var type: String? = "business"
    @State private var usernameStatus = MonarchUsernameAvailabilityStatus.idle
    @State private var hasSubmitted = false
    @State private var isCreating = false

    private var nameError: String? {
        let count = name.trimmingCharacters(in: .whitespacesAndNewlines).count
        guard hasSubmitted || count > 0 else { return nil }
        if count < 4 { return "Name must be at least 4 characters" }
        if count > 25 { return "Name must be at most 25 characters" }
        return nil
    }

    nonisolated private static func checkUsername(_ handle: String) async -> MonarchUsernameAvailabilityResult? {
        guard !handle.isEmpty else { return nil }
        // Call the product's availability lookup here.
        return handle.lowercased() == "acmeinc"
            ? MonarchUsernameAvailabilityResult(isValid: false, message: "That username is taken")
            : MonarchUsernameAvailabilityResult(isValid: true)
    }

    var body: some View {
        MonarchButton("Create workspace", variant: .primary) { isPresented = true }
            .sheet(isPresented: $isPresented) {
                NavigationStack {
                    ScrollView {
                        VStack(alignment: .leading, spacing: theme.spacing.space4) {
                            MonarchTextField("Workspace name", text: $name, prompt: "Acme Inc.", error: nameError, isRequired: true)
                            MonarchUsernameAvailabilityInput(
                                "Workspace username",
                                text: $username,
                                prompt: "acme",
                                helper: "Letters and numbers only, 5 to 30 characters.",
                                prefix: "@",
                                isRequired: true,
                                onStatusChange: { status, _ in usernameStatus = status },
                                validate: { handle in await Self.checkUsername(handle) }
                            )
                            MonarchRadioCardGroup(
                                "Type",
                                selection: $type,
                                options: [
                                    MonarchRadioCardOption("creator", title: "Creator", description: "For individual creators and personal projects", systemImage: "person"),
                                    MonarchRadioCardOption("business", title: "Business", description: "For teams and companies", systemImage: "building.2"),
                                ],
                                columns: 2,
                                compactColumns: 2
                            )
                            MonarchButton("Create workspace", variant: .primary, isLoading: isCreating, fullWidth: true) {
                                hasSubmitted = true
                                guard nameError == nil, type != nil, usernameStatus == .valid else { return }
                                isCreating = true
                                // Create the workspace, then set isCreating to false and isPresented to false.
                            }
                        }
                        .monarchHelperAbove()
                        .padding(theme.spacing.space4)
                    }
                    .navigationTitle("Create new workspace")
                    .toolbar {
                        ToolbarItem(placement: .cancellationAction) {
                            Button("Cancel") { isPresented = false }
                                .disabled(isCreating)
                        }
                    }
                }
                .interactiveDismissDisabled(isCreating)
            }
    }
}

/// data-subject-request-form: Public privacy request form
private struct DataSubjectRequestFormExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var type: String?
    @State private var isAgent = false
    @State private var name = ""
    @State private var email = ""
    @State private var country: String?
    @State private var details = ""
    @State private var isAccurate = false
    @State private var showsErrors = false
    @State private var reference: String?

    private var emailError: String? {
        guard showsErrors else { return nil }
        return email.contains("@") ? nil : "Enter an email address like name@example.com."
    }

    var body: some View {
        if let reference {
            MonarchBanner("Request received", message: "Your reference is \(reference).", tone: .success)
        } else {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                MonarchRadioCardGroup(
                    "What would you like to do?",
                    selection: $type,
                    options: [
                        MonarchRadioCardOption("access", title: "Get a copy of my data", description: "Receive a copy of the personal information held about you."),
                        MonarchRadioCardOption("delete", title: "Delete my data", description: "Ask for your personal information to be deleted."),
                        MonarchRadioCardOption("correct", title: "Correct my data", description: "Fix personal information that is wrong or incomplete."),
                        MonarchRadioCardOption("object", title: "Object to or restrict processing", description: "Ask for your information to stop being used, or to be used less."),
                        MonarchRadioCardOption("opt-out", title: "Opt out of sale or sharing", description: "Stop your information from being sold or shared for advertising."),
                        MonarchRadioCardOption("withdraw-consent", title: "Withdraw consent", description: "Take back consent you gave earlier, for example for marketing."),
                    ],
                    columns: 2,
                    compactColumns: 2,
                    isRequired: true
                )
                MonarchRadioCardGroup(
                    "Who is this request for?",
                    selection: Binding(get: { isAgent ? "agent" : "myself" }, set: { isAgent = $0 == "agent" }),
                    options: [
                        MonarchRadioCardOption("myself", title: "Myself"),
                        MonarchRadioCardOption("agent", title: "Someone I am authorized to act for"),
                    ],
                    columns: 2,
                    compactColumns: 2
                )
                MonarchFormField(isAgent ? "Their full name" : "Full name", optionalText: "Optional") {
                    MonarchTextField(isAgent ? "Their full name" : "Full name", text: $name, prompt: "", labelVisibility: .hidden)
                }
                MonarchFormField(
                    isAgent ? "Their email" : "Email",
                    helper: "Used to identify the account and to reply about this request.",
                    error: emailError,
                    isRequired: true
                ) {
                    MonarchTextField(isAgent ? "Their email" : "Email", text: $email, prompt: "", labelVisibility: .hidden)
                }
                MonarchCountrySelect(
                    "Country or region where the person lives",
                    selection: $country,
                    prompt: "Choose a country or region",
                    error: showsErrors && country == nil ? "Choose a country or region." : nil,
                    isRequired: true
                )
                MonarchFormField("Details", helper: "Anything that helps find the information or explains the request.", isRequired: type == "correct", optionalText: "Optional") {
                    MonarchTextField("Details", text: $details, prompt: "", axis: .vertical, lineLimit: 3...6, labelVisibility: .hidden)
                }
                MonarchInlineNotice("To protect the account, we will email a link to confirm the request before acting on it.", tone: .info)
                Toggle("The information I gave is accurate", isOn: $isAccurate)
                    .toggleStyle(.monarchCheckbox)
                MonarchButton("Send request", variant: .primary, fullWidth: true) {
                    showsErrors = true
                    guard type != nil, emailError == nil, country != nil, isAccurate else { return }
                    // Send the request to the app's privacy service here.
                    reference = "DSR-1042"
                }
            }
        }
    }
}

/// deactivate-flow: Deactivate with consequences and a reason
private struct DeactivateFlowExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isPresented = PreviewMode.presented ? true : false
    @State private var isDeactivated = false
    @State private var reason = ""
    @State private var isWorking = false
    @State private var failure: String?

    private func confirm() {
        isWorking = true
        failure = nil
        Task {
            // The app's request, with reason. A thrown error goes in failure and the sheet stays open.
            try? await Task.sleep(for: .milliseconds(300))
            isWorking = false
            isDeactivated.toggle()
            isPresented = false
        }
    }
    private let asksReason = true
    private let subject = "this partnership"
    private let reactivateFrom = "Settings › Partners"

    var body: some View {
        MonarchButton(isDeactivated ? "Reactivate" : "Deactivate", variant: .warning) { isPresented = true }
            .sheet(isPresented: $isPresented) {
                ScrollView {
                    VStack(alignment: .leading, spacing: theme.spacing.space4) {
                        Image(systemName: "exclamationmark.triangle")
                            .font(.system(size: 20))
                            .foregroundStyle(theme.colors.warningStrong)
                            .frame(width: 40, height: 40)
                            .background(theme.colors.warningSubtle, in: RoundedRectangle(cornerRadius: 10))
                            .accessibilityHidden(true)
                        Text(isDeactivated ? "Reactivate \(subject)?" : "Deactivate \(subject)?")
                            .monarchTextStyle(.title)
                            .accessibilityAddTraits(.isHeader)
                        Text(
                            isDeactivated
                                ? "It starts working again straight away."
                                : "It stops working until you turn it back on. Nothing is deleted."
                        )
                        .monarchTextStyle(.body)
                        if !isDeactivated {
                            Label("You can reactivate it at any time from \(reactivateFrom).", systemImage: "arrow.uturn.backward")
                                .monarchTextStyle(.body)
                        }
                        MonarchConsequenceList(
                            isDeactivated
                                ? [MonarchConsequence(.changed, "Shared reports update again")]
                                : [
                                    MonarchConsequence(.changed, "New referrals are not tracked"),
                                    MonarchConsequence(.changed, "The partner cannot sign in to the portal"),
                                    MonarchConsequence(.kept, "Past referrals and payouts stay in reports"),
                                ],
                            heading: isDeactivated ? "Once it is reactivated" : "While it is deactivated"
                        )
                        if asksReason {
                            MonarchTextField("Reason (optional)", text: $reason, helper: "Kept with the change history.")
                        }
                        if let failure {
                            MonarchInlineNotice(failure, tone: .danger)
                        }
                        MonarchButton(
                            isDeactivated ? "Reactivate" : "Deactivate",
                            variant: .primary,
                            isLoading: isWorking,
                            fullWidth: true,
                            action: confirm
                        )
                        MonarchButton("Cancel", variant: .ghost, fullWidth: true) { isPresented = false }
                    }
                    .padding(theme.spacing.space4)
                }
                .presentationDetents([.medium, .large])
                .interactiveDismissDisabled(isWorking)
            }
    }
}

/// delete-workspace-flow: From a danger zone, with export, transfer and step-up
private struct DeleteWorkspaceFlowExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isOpen = PreviewMode.presented ? true : false
    @State private var typed = ""
    @State private var isMatched = false
    @State private var isVerifying = false
    @State private var isDeleting = false
    @State private var isDone = false
    @State private var failure: String?

    private var impact: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                VStack(alignment: .leading, spacing: theme.spacing.space2) {
                    Text("Step 1 of 4").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                    ProgressView(value: 0.25).progressViewStyle(.monarchLinear)
                }
                Text("Deleting north-studio removes it and everything in it for every member. This cannot be undone.").monarchTextStyle(.body)
                MonarchConsequenceList(
                    [
                        MonarchConsequence(.removed, "apps", count: 4),
                        MonarchConsequence(.removed, "records", count: 18_340),
                        MonarchConsequence(.changed, "members lose access", count: 12),
                        MonarchConsequence(.changed, "active subscription is cancelled", count: 1),
                        MonarchConsequence(.changed, "custom domains are disconnected", count: 2),
                    ],
                    heading: "What will be deleted",
                    isGrouped: true
                )
                HStack {
                    MonarchButton("Cancel") { isOpen = false }
                    NavigationLink("Continue", value: "confirm")
                        .buttonStyle(.monarch(.primary, fullWidth: true))
                }
            }
            .padding(theme.spacing.space6)
        }
        .navigationTitle("Delete workspace")
        .navigationDestination(for: String.self) { _ in confirm }
    }

    private var confirm: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text("This cannot be undone.").monarchTextStyle(.body)
            MonarchTypeToConfirmInput(phrase: "north-studio", text: $typed, onMatchChange: { isMatched = $0 })
            if let failure {
                MonarchInlineNotice(failure, tone: .danger)
            }
            MonarchButton("Delete workspace", variant: .danger, isLoading: isDeleting, fullWidth: true) {
                isVerifying = true
            }
            .disabled(!isMatched)
        }
        .padding(theme.spacing.space6)
        .navigationTitle("Confirm deletion")
        .sheet(isPresented: $isVerifying) {
            MonarchStepUpAuthDialog(
                description: "Deleting a workspace needs you to confirm your identity.",
                onVerified: { delete() },
                onVerify: { _ in
                    // The app re-authenticates the person here.
                }
            )
        }
    }

    private func delete() {
        isDeleting = true
        failure = nil
        Task {
            do {
                // The app deletes the workspace here.
                try await Task.sleep(for: .milliseconds(300))
                isDone = true
            } catch {
                failure = "The workspace couldn’t be deleted. Try again."
            }
            isDeleting = false
        }
    }

    var body: some View {
        MonarchSectionCard("Danger zone", description: "These actions affect everyone in the workspace.", tone: .danger) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text("Delete this workspace").monarchTextStyle(.bodyStrong)
                Text("Removes the workspace, its apps and its records for every member.")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                MonarchButton("Delete workspace", variant: .danger) { isOpen = true }
            }
        }
        .sheet(isPresented: $isOpen) {
            NavigationStack {
                if isDone {
                    MonarchEmptyState(
                        "Workspace deleted",
                        message: "north-studio and everything in it has been deleted.",
                        systemImage: "checkmark.circle",
                        kind: .success,
                        actionTitle: "Close",
                        action: { isOpen = false }
                    )
                } else {
                    impact
                }
            }
            .interactiveDismissDisabled(isDeleting)
        }
    }
}

