/// gdpr-erase-flow: Erase with retained records, step-up and audit reference
private struct GdprEraseFlowExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isOpen = PreviewMode.presented ? true : true
    @State private var understands = false
    @State private var typed = ""
    @State private var isMatched = false
    @State private var isVerifying = false
    @State private var isErasing = false
    @State private var auditID: String?

    private var review: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                Text("What happens").monarchTextStyle(.heading)
                VStack(alignment: .leading, spacing: theme.spacing.space2) {
                    Text("Step 1 of 2").monarchTextStyle(.caption).foregroundStyle(theme.colors.textMuted)
                    ProgressView(value: 0.5).progressViewStyle(.monarchLinear)
                }
                Text("This erases the personal data held about " + "Alex Kim" + ".")
                    .monarchTextStyle(.body)
                MonarchConsequenceList(
                    [
                        MonarchConsequence(.removed, "Profile, name and contact details"),
                        MonarchConsequence(.removed, "messages and comments", count: 214),
                        MonarchConsequence(.removed, "uploaded files", count: 37),
                        MonarchConsequence(.removed, "Sign-in history and device records"),
                    ],
                    heading: "Will be erased"
                )
                MonarchConsequenceList(
                    [
                        MonarchConsequence(.kept, "Invoices and payment records", detail: "Kept for the retention period your policy sets, then deleted"),
                        MonarchConsequence(.kept, "Audit log entries", detail: "With the name replaced by a reference"),
                    ],
                    heading: "Will be kept"
                )
                MonarchBanner("This cannot be undone", message: "Erased data cannot be recovered, by you or by support.", tone: .danger)
                HStack(spacing: theme.spacing.space3) {
                    MonarchButton("Cancel", variant: .secondary, fullWidth: true) { isOpen = false }
                    NavigationLink("Continue", value: "confirm")
                        .buttonStyle(.monarch(.primary, fullWidth: true))
                }
            }
            .padding(theme.spacing.space6)
        }
        .navigationTitle("Erase personal data")
        .navigationDestination(for: String.self) { _ in confirm }
    }

    private var confirm: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Toggle("I understand this cannot be undone", isOn: $understands)
                .toggleStyle(.monarchCheckbox)
            Text("Erase the personal data of " + "Alex Kim" + " now.")
                .monarchTextStyle(.body)
            MonarchTypeToConfirmInput(phrase: "alex@example.com", text: $typed, onMatchChange: { isMatched = $0 })
            MonarchButton("Erase data", variant: .danger, isLoading: isErasing, fullWidth: true) {
                isVerifying = true
            }
            .disabled(!(understands && isMatched))
        }
        .padding(theme.spacing.space6)
        .navigationTitle("Confirm the erasure")
        .sheet(isPresented: $isVerifying) {
            MonarchStepUpAuthDialog(
                description: "Erasing personal data needs you to confirm your identity.",
                onVerified: { erase() },
                onVerify: { _ in
                    // The app re-authenticates the person here.
                }
            )
        }
    }

    private func erase() {
        isErasing = true
        Task {
            // The app erases the data and returns the audit log entry.
            try? await Task.sleep(for: .milliseconds(300))
            isErasing = false
            auditID = "evt_7Q2K9X"
        }
    }

    var body: some View {
        MonarchButton("Erase personal data", variant: .danger) { isOpen = true }
            .sheet(isPresented: $isOpen) {
                NavigationStack {
                    if let auditID {
                        VStack(alignment: .leading, spacing: theme.spacing.space4) {
                            MonarchEmptyState("Personal data erased", systemImage: "checkmark.circle", kind: .success)
                            LabeledContent("Reference", value: auditID)
                                .labeledContentStyle(.monarch)
                            MonarchButton("Close", fullWidth: true) { isOpen = false }
                        }
                        .padding(theme.spacing.space6)
                    } else {
                        review
                    }
                }
                .interactiveDismissDisabled(isErasing)
            }
    }
}

