/// leave-workspace-flow: Leave from a danger zone
private struct LeaveWorkspaceFlowExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isConfirming = false
    @State private var isBlocked = false
    @State private var isLeaving = false
    @State private var failure: String?
    private let isLastOwner = false
    private let apps = ["Projects", "Docs", "Calendar"]

    private func leave() {
        isLeaving = true
        failure = nil
        Task {
            do {
                // The app removes the person from the workspace here.
                try await Task.sleep(for: .milliseconds(300))
                isLeaving = false
                isConfirming = false
            } catch {
                isLeaving = false
                failure = "Couldn’t leave the workspace. Try again."
            }
        }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space2) {
            // The heading sits outside the card, which has a red edge and its button at the right, as on the web.
            Text("Danger zone").monarchTextStyle(.bodyStrong).foregroundStyle(theme.colors.dangerStrong)
            HStack(alignment: .center, spacing: theme.spacing.space3) {
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    Text("Leave this workspace").monarchTextStyle(.label).fontWeight(.medium)
                    Text("You lose access to its projects and documents.")
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                }
                .frame(maxWidth: .infinity, alignment: .leading)
                MonarchButton("Leave workspace", variant: .danger, size: .sm) {
                    if isLastOwner {
                        isBlocked = true
                    } else {
                        isConfirming = true
                    }
                }
                .fixedSize()
            }
            .padding(theme.spacing.space3)
            .background(theme.colors.bgSurface)
            .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
            .overlay(RoundedRectangle(cornerRadius: 12, style: .continuous).strokeBorder(theme.colors.dangerBorder))
            .overlay(alignment: .leading) { Rectangle().fill(theme.colors.dangerSolid).frame(width: 3) }
            .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
        }
        .alert("You can’t leave yet", isPresented: $isBlocked) {
            Button("Transfer ownership") {
                // Open the app's transfer ownership flow.
            }
            Button("Close", role: .cancel) {}
        } message: {
            Text("You are the only owner. Transfer ownership to another member before you leave.")
        }
        .sheet(isPresented: $isConfirming) {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    Text("Leave " + "Northfield" + "?")
                        .monarchTextStyle(.heading)
                        .accessibilityAddTraits(.isHeader)
                    Text("You are removed from the workspace straight away.")
                        .monarchTextStyle(.body)
                    MonarchConsequenceList([
                        MonarchConsequence(.removed, "You lose access to " + apps.joined(separator: ", ")),
                        MonarchConsequence(.kept, "What you created stays in the workspace for the other members"),
                        MonarchConsequence(.warning, "You need a new invite to come back"),
                    ])
                    if let failure {
                        MonarchInlineNotice(failure, tone: .danger)
                    }
                    MonarchButton("Leave workspace", variant: .danger, isLoading: isLeaving, fullWidth: true, action: leave)
                    MonarchButton("Cancel", variant: .ghost, fullWidth: true) { isConfirming = false }
                        .disabled(isLeaving)
                }
                .padding(theme.spacing.space6)
            }
            .interactiveDismissDisabled(isLeaving)
            .presentationDetents([.medium, .large])
        }
    }
}

