/// remove-member-flow: Hand over open work, then remove, with Undo
private struct RemoveMemberFlowExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var toasts = MonarchToastCenter()
    @State private var isOpen = PreviewMode.presented ? true : false
    @State private var allTo: String?
    @State private var isPerKind = false
    @State private var assignments: [String: String] = [:]
    @State private var isConfirming = false
    @State private var isRemoving = false
    private let work = [
        (id: "issues", count: 12, label: "open issues"),
        (id: "reviews", count: 3, label: "pending reviews"),
        (id: "docs", count: 5, label: "draft documents"),
    ]
    private let people = [
        MonarchAssigneePerson(id: "me", name: "Sam Rivera", email: "sam@example.com"),
        MonarchAssigneePerson(id: "m1", name: "Alex Morgan", email: "alex@example.com"),
        MonarchAssigneePerson(id: "m2", name: "Priya Shah", email: "priya@example.com"),
        MonarchAssigneePerson(id: "m3", name: "Jordan Lee", email: "jordan@example.com"),
    ]

    private var target: String? { people.first { $0.id == allTo }?.name }

    /// Who takes one kind of work: the person chosen for it, or the one chosen for all work.
    private func assignee(of kind: String) -> String? {
        people.first { $0.id == (isPerKind ? assignments[kind] : allTo) }?.name
    }

    private var handOver: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    Text("Step 1 of 2")
                        .monarchTextStyle(.caption)
                        .foregroundStyle(theme.colors.textMuted)
                    ProgressView(value: 0.5)
                        .progressViewStyle(.monarchLinear)
                        .accessibilityHidden(true)
                }
                Text("Hand over their open work").monarchTextStyle(.heading).accessibilityAddTraits(.isHeader)
                Text("Choose who takes over what Jordan Lee still owns, or leave it unassigned.")
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                if isPerKind {
                    ForEach(work, id: \.id) { item in
                        MonarchAssigneePicker(
                            item.label,
                            selection: Binding(get: { assignments[item.id] }, set: { assignments[item.id] = $0 }),
                            people: people,
                            currentUserID: "me",
                            showsAssignToMe: false,
                            labels: MonarchAssigneePickerLabels(unassigned: "Leave unassigned")
                        )
                    }
                } else {
                    MonarchAssigneePicker(
                        "Reassign all open work to",
                        selection: $allTo,
                        people: people,
                        currentUserID: "me",
                        showsAssignToMe: false,
                        labels: MonarchAssigneePickerLabels(unassigned: "Leave unassigned")
                    )
                }
                Toggle("Choose a person for each kind of work", isOn: $isPerKind)
                    .toggleStyle(.monarchCheckbox)
                    .monarchTextStyle(.body)
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    ForEach(work, id: \.id) { item in
                        Text("\u{2022}  \(item.count) \(item.label)")
                            .monarchTextStyle(.body)
                            .foregroundStyle(theme.colors.textMuted)
                    }
                }
            }
            .padding(theme.spacing.space4)
        }
        .background(theme.colors.bgCanvas)
    }

    private func remove() {
        isRemoving = true
        Task {
            // Send the removal and each work item's assignee to the server here.
            isRemoving = false
            isOpen = false
            toasts.show("Jordan Lee removed", actionTitle: "Undo", duration: 8) {
                // Restore the membership and the work on the server.
            }
        }
    }

    var body: some View {
        MonarchButton("Remove Jordan Lee", systemImage: "person.badge.minus", variant: .danger) {
            allTo = nil
            isOpen = true
        }
        .sheet(isPresented: $isOpen) {
            NavigationStack {
                handOver
                    .navigationTitle("Remove Jordan Lee")
                    .toolbar {
                        ToolbarItem(placement: .cancellationAction) {
                            Button("Cancel") { isOpen = false }.disabled(isRemoving)
                        }
                        ToolbarItem(placement: .confirmationAction) {
                            if isRemoving {
                                ProgressView().accessibilityLabel("Removing Jordan Lee")
                            } else {
                                Button("Continue") { isConfirming = true }
                            }
                        }
                    }
                    .confirmationDialog(
                        "Remove Jordan Lee?",
                        isPresented: $isConfirming,
                        titleVisibility: .visible,
                        actions: {
                            Button("Remove member", role: .destructive) { remove() }
                            Button("Cancel", role: .cancel) {}
                        },
                        message: { Text("They lose access to the workspace straight away.") }
                    )
            }
            .interactiveDismissDisabled(isRemoving)
        }
        .monarchToastHost(toasts)
    }
}

/// revoke-access-flow: API key with type-to-confirm and step-up
private struct RevokeAccessFlowExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isConfirming = PreviewMode.presented ? true : false
    @State private var isSteppingUp = false
    @State private var phrase = ""
    @State private var isRevoking = false
    @State private var failure: String?
    private let keyName = "Build server"
    private let keyPrefix = "sk_live_…4f2a · read and write"
    private let lastUsed = Date().addingTimeInterval(-3.0 * 3_600)

    private func revoke() {
        isRevoking = true
        failure = nil
        Task {
            do {
                // The app revokes the key on the server here.
                try await Task.sleep(for: .milliseconds(300))
                isRevoking = false
                isConfirming = false
            } catch {
                isRevoking = false
                failure = "Couldn’t revoke the key. Try again."
            }
        }
    }

    var body: some View {
        MonarchButton("Revoke key", variant: .danger) {
            phrase = ""
            isConfirming = true
        }
        .accessibilityLabel("Revoke \(keyName)")
        .sheet(isPresented: $isConfirming) {
            ScrollView {
                VStack(alignment: .leading, spacing: theme.spacing.space4) {
                    MonarchIcon(systemName: "exclamationmark.triangle")
                        .foregroundStyle(theme.colors.dangerStrong)
                        .frame(width: 40, height: 40)
                        .background(Circle().fill(theme.colors.dangerSubtle))
                        .accessibilityHidden(true)
                    Text("Revoke API key?")
                        .monarchTextStyle(.heading)
                        .accessibilityAddTraits(.isHeader)
                    Text("A revoked key cannot be restored. Create a new key if you still need access.")
                        .monarchTextStyle(.body)
                        .foregroundStyle(theme.colors.textMuted)
                    MonarchCard {
                        VStack(alignment: .leading, spacing: theme.spacing.space1) {
                            Text(keyName).monarchTextStyle(.bodyStrong)
                            Text(keyPrefix)
                                .monarchTextStyle(.caption)
                                .foregroundStyle(theme.colors.textMuted)
                            Text("Last used \(lastUsed.formatted(.relative(presentation: .named)))")
                                .monarchTextStyle(.caption)
                                .foregroundStyle(theme.colors.textMuted)
                        }
                        .frame(maxWidth: .infinity, alignment: .leading)
                    }
                    .accessibilityElement(children: .combine)
                    MonarchConsequenceList(
                        [MonarchConsequence(.removed, "Apps and scripts using this key stop working immediately")],
                        heading: "What happens"
                    )
                    MonarchTypeToConfirmInput(phrase: keyName, text: $phrase)
                    if let failure {
                        MonarchInlineNotice(failure, tone: .danger)
                    }
                    HStack(spacing: theme.spacing.space2) {
                        Spacer(minLength: 0)
                        MonarchButton("Cancel", variant: .secondary) { isConfirming = false }
                            .disabled(isRevoking)
                        MonarchButton("Revoke key", variant: .danger, isLoading: isRevoking) {
                            isSteppingUp = true
                        }
                        .disabled(phrase != keyName)
                    }
                }
                .padding(theme.spacing.space6)
            }
            .interactiveDismissDisabled(isRevoking)
            .sheet(isPresented: $isSteppingUp) {
                MonarchStepUpAuthDialog(
                    description: "Revoking access needs you to confirm it’s you.",
                    onVerified: revoke,
                    onVerify: { credential in
                        // Send the credential to the server; throw if it is refused.
                        try await Task.sleep(for: .milliseconds(300))
                    }
                )
            }
        }
    }
}

