/// transfer-ownership-flow: From a danger zone
private struct TransferOwnershipFlowExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var isOpen = PreviewMode.presented ? true : false
    @State private var path: [Int] = []
    @State private var owner: String?
    @State private var isTransferring = false
    private let steps = [
        MonarchStepperStep(id: "pick", label: "New owner"),
        MonarchStepperStep(id: "review", label: "What changes"),
        MonarchStepperStep(id: "confirm", label: "Confirm"),
    ]
    private let members = [
        MonarchEntityPickerEntity(id: "m1", name: "Alex Morgan", description: "alex@example.com"),
        MonarchEntityPickerEntity(id: "m2", name: "Priya Shah", description: "priya@example.com"),
        MonarchEntityPickerEntity(id: "m3", name: "Jordan Lee", description: "jordan@example.com", hint: "Only admins can become the owner", isDisabled: true),
        MonarchEntityPickerEntity(id: "m4", name: "Chris Novak", description: "chris@example.com", hint: "Invite not accepted yet", isDisabled: true),
    ]
    private var ownerName: String { members.first { $0.id == owner }?.name ?? "" }

    private func step(_ index: Int) -> some View {
        ScrollView {
            VStack(alignment: .leading, spacing: theme.spacing.space4) {
                MonarchStepper(steps, current: index)
                switch index {
                case 0:
                    Text("Choose the new owner")
                        .monarchTextStyle(.heading)
                        .accessibilityAddTraits(.isHeader)
                    Text("The new owner gets full control of the workspace, including billing.")
                        .monarchTextStyle(.body)
                        .foregroundStyle(theme.colors.textMuted)
                    MonarchEntityPicker("New owner", selection: $owner, entities: members, prompt: "Choose a member")
                    if owner == nil {
                        Text("Choose a member to continue.")
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                    }
                    MonarchButton("Continue", variant: .primary, fullWidth: true) { path.append(1) }
                        .disabled(owner == nil)
                case 1:
                    MonarchConsequenceList([MonarchConsequence(.changed, "You become an admin")], heading: "For you")
                    MonarchConsequenceList([MonarchConsequence(.changed, "\(ownerName) becomes the owner")], heading: "For \(ownerName)")
                    MonarchButton("Continue", variant: .primary, fullWidth: true) { path.append(2) }
                default:
                    MonarchButton("Transfer ownership", variant: .danger, isLoading: isTransferring, fullWidth: true) {
                        // Start the transfer on the server here, then close the sheet.
                        isTransferring = true
                    }
                }
            }
            .padding(theme.spacing.space4)
        }
    }

    var body: some View {
        MonarchSectionCard("Danger zone", tone: .danger) {
            VStack(alignment: .leading, spacing: theme.spacing.space1) {
                Text("Transfer ownership").monarchTextStyle(.bodyStrong)
                Text("Another member becomes the owner. You choose your role afterwards.")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
                MonarchButton("Transfer ownership", variant: .secondary) { isOpen = true }
            }
        }
        .sheet(isPresented: $isOpen) {
            NavigationStack(path: $path) {
                step(0)
                    .navigationTitle("Transfer ownership")
                    .toolbar {
                        ToolbarItem(placement: .cancellationAction) { Button("Cancel") { isOpen = false } }
                    }
                    .navigationDestination(for: Int.self) { index in step(index) }
            }
            .interactiveDismissDisabled(isTransferring)
        }
    }
}

/// two-factor-setup: Full setup (enter 000000 to see a wrong code)
private struct TwoFactorSetupExample0: View {
    @Environment(\.monarchTheme) private var theme
    @Environment(\.openURL) private var openURL
    @State private var step = 0
    @State private var code = ""
    @State private var codeError: String?
    private let secret = "JBSWY3DPEHPK3PXPJBSWY3DP"
    private var otpauth: URL? { URL(string: "otpauth://totp/Example:" + "sam@example.com" + "?secret=" + secret + "&issuer=Example") }
    private let codes: [MonarchRecoveryCode] = ["k7f2-9qd4", "m3x8-2hp6", "r5c1-8vt3", "w9n4-6bz2", "a2j7-4ls9", "e6y3-1gu5"]
    private let steps = [
        MonarchStepperStep(id: "scan", label: "Connect your app"),
        MonarchStepperStep(id: "verify", label: "Enter a code"),
        MonarchStepperStep(id: "recovery", label: "Save recovery codes"),
    ]

    private func qrCode(_ text: String) -> Image? {
        guard let filter = CIFilter(name: "CIQRCodeGenerator") else { return nil }
        filter.setValue(Data(text.utf8), forKey: "inputMessage")
        guard let output = filter.outputImage,
            let image = CIContext().createCGImage(output, from: output.extent)
        else { return nil }
        return Image(decorative: image, scale: 1)
    }

    private func verifyCode() {
        // The app checks the code with the server, then moves on or sets codeError.
        codeError = code.count == 6 ? nil : "Enter all 6 digits."
        if codeError == nil { step = 2 }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            MonarchButton("Turn on two-step verification", variant: .primary) { step = 0 }
            MonarchStepper(steps, current: step)
            switch step {
            case 0:
                Text("Set up two-step verification")
                    .monarchTextStyle(.title)
                    .accessibilityAddTraits(.isHeader)
                Text("Scan this QR code with an authenticator app, such as 1Password, Google Authenticator or Microsoft Authenticator.")
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                if let otpauth, let qr = qrCode(otpauth.absoluteString) {
                    VStack(spacing: theme.spacing.space2) {
                        MonarchCard {
                            qr.interpolation(.none)
                                .resizable()
                                .scaledToFit()
                                .frame(width: theme.spacing.space24 * 2)
                                .accessibilityLabel("QR code for your authenticator app")
                                .accessibilityAddTraits(.isImage)
                        }
                        .fixedSize()
                        Text(verbatim: "sam@example.com")
                            .monarchTextStyle(.caption)
                            .foregroundStyle(theme.colors.textMuted)
                    }
                    .frame(maxWidth: .infinity)
                }
                Text("Can’t scan it? Enter this key in the app instead.")
                    .monarchTextStyle(.body)
                    .foregroundStyle(theme.colors.textMuted)
                MonarchCopyField("Setup key", value: secret, isLabelHidden: true)
                HStack(spacing: theme.spacing.space2) {
                    Spacer(minLength: 0)
                    MonarchButton("Cancel", variant: .secondary) { step = 0 }
                    MonarchButton("Next", variant: .primary) { step = 1 }
                }
            case 1:
                MonarchOtpPinInput("6-digit code", text: $code, error: codeError) { _ in verifyCode() }
                MonarchButton("Verify", variant: .primary, action: verifyCode)
            default:
                MonarchRecoveryCodes(codes, onAcknowledge: { step = 0 })
            }
        }
    }
}

