/// workspace-onboarding-form: Onboarding with availability check (try "acme")
private struct WorkspaceOnboardingFormExample0: View {
    @Environment(\.monarchTheme) private var theme
    @State private var name = ""
    @State private var username = ""
    @State private var type: String?
    @State private var usernameStatus = MonarchUsernameAvailabilityStatus.idle
    @State private var hasSubmitted = false
    @State private var isCreating = false

    private var nameError: String? {
        let count = name.trimmingCharacters(in: .whitespacesAndNewlines).count
        guard hasSubmitted || count > 0 else { return nil }
        if count < 4 { return "Name must be at least 4 characters" }
        if count > 25 { return "Name must be at most 25 characters" }
        return nil
    }

    nonisolated private static func checkUsername(_ handle: String) async -> MonarchUsernameAvailabilityResult? {
        guard !handle.isEmpty else { return nil }
        guard handle.allSatisfy({ $0.isASCII && ($0.isLetter || $0.isNumber) }) else {
            return MonarchUsernameAvailabilityResult(isValid: false, message: "Use letters and numbers only")
        }
        guard (5...30).contains(handle.count) else {
            return MonarchUsernameAvailabilityResult(isValid: false, message: "Use 5 to 30 characters")
        }
        // Call the product's availability lookup here.
        return MonarchUsernameAvailabilityResult(isValid: handle.lowercased() != "acmeinc")
    }

    var body: some View {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            MonarchTextField("Workspace name", text: $name, prompt: "Acme Inc.", error: nameError, isRequired: true)
            MonarchUsernameAvailabilityInput(
                "Workspace username",
                text: $username,
                prompt: "acme",
                helper: "Letters and numbers only, 5 to 30 characters.",
                prefix: "@",
                isRequired: true,
                onStatusChange: { status, _ in usernameStatus = status },
                validate: { handle in await Self.checkUsername(handle) }
            )
            .monarchHelperAbove()
            MonarchRadioCardGroup(
                "Type",
                selection: $type,
                options: [
                    MonarchRadioCardOption("creator", title: "Creator", description: "For individual creators and personal projects", systemImage: "person"),
                    MonarchRadioCardOption("business", title: "Business", description: "For teams and companies", systemImage: "building.2"),
                ],
                columns: 2,
                compactColumns: 2
            )
            if hasSubmitted && type == nil {
                Label("Choose a workspace type", systemImage: "exclamationmark.circle")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.dangerStrong)
            }
            MonarchButton("Continue", variant: .primary, isLoading: isCreating, fullWidth: true) {
                hasSubmitted = true
                guard nameError == nil, type != nil, usernameStatus == .valid else { return }
                isCreating = true
                // Create the workspace, then set isCreating to false.
            }
        }
    }
}

